export const getUpdateGoalUrl = (id: string) => {
  return `/progress/goals/${id}`;
};

/**
 * Requires If-Match with the goal's ETag (428 goal.if_match_required, 412 goal.version_mismatch). An achieved goal is locked: only title, description and sort order change (409 goal.locked). A new target is checked against a freshly measured baseline.
 * @summary Change one of your goals
 */
export const updateGoal = async (
  id: string,
  updateGoalRequest: UpdateGoalRequest,
  options?: Parameters<typeof apiFetch>[1],
): Promise<GoalView> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return apiFetch<GoalView>(getUpdateGoalUrl(id), {
    ...options,
    method: "PATCH",
    headers: {
      "Content-Type": "application/json",
      ...getHeaders(options?.headers),
    },
    body: JSON.stringify(updateGoalRequest),
  });
};

