/**
 * Send exactly the goal's milestone ids in the new order (400 goal.reorder_mismatch); thresholds must still increase in that order (400 goal.invalid_milestones).
 * @summary Reorder the milestones of one of your goals
 */
export const reorderGoalMilestones = async (
  id: string,
  reorderMilestonesRequest: ReorderMilestonesRequest,
  options?: Parameters<typeof apiFetch>[1],
): Promise<MilestoneView[]> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return apiFetch<MilestoneView[]>(getReorderGoalMilestonesUrl(id), {
    ...options,
    method: "PATCH",
    headers: {
      "Content-Type": "application/json",
      ...getHeaders(options?.headers),
    },
    body: JSON.stringify(reorderMilestonesRequest),
  });
};

